create policy communication_threads_coach_scope on public.communication_threads for all to authenticated using (team_id is not null and app.can_access_coach_team(team_id)) with check (team_id is not null and app.can_access_coach_team(team_id));
create policy communication_messages_coach_scope on public.communication_messages for all to authenticated using (exists (select 1 from public.communication_threads t where t.id=thread_id and t.team_id is not null and app.can_access_coach_team(t.team_id))) with check (exists (select 1 from public.communication_threads t where t.id=thread_id and t.team_id is not null and app.can_access_coach_team(t.team_id)));
create policy communication_message_recipients_coach_scope on public.communication_message_recipients for all to authenticated using (exists (select 1 from public.communication_messages m join public.communication_threads t on t.id=m.thread_id where m.id=message_id and t.team_id is not null and app.can_access_coach_team(t.team_id))) with check (exists (select 1 from public.communication_messages m join public.communication_threads t on t.id=m.thread_id where m.id=message_id and t.team_id is not null and app.can_access_coach_team(t.team_id)));